729	// ---------------------------------------------------------------------------
730	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
731	// ---------------------------------------------------------------------------
732	
733	function describeError(e: unknown): string {
734	  return e instanceof Error ? e.message : String(e);
735	}
736	
737	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
738	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
739	  let text: string;
740	  try {
741	    text = await readFile(configPath, 'utf8');
742	  } catch (e) {
743	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
744	  }
745	
746	  let raw: unknown;
747	  try {
748	    raw = JSON.parse(text);
749	  } catch (e) {
750	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
751	  }
752	
753	  try {
754	    return validateConfig(raw);
755	  } catch (e) {
756	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
757	  }
758	}
759	
760	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
761	  return buildState(version, await loadSpecsFromFile(configPath));
762	}
763	
764	// ---------------------------------------------------------------------------
765	// 离线兼容报告（compare 子命令）
766	// ---------------------------------------------------------------------------
767	//
768	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
769	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
770	// 响应状态/头/正文/延迟与序列差异不影响结论。
771	//
772	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
773	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
774	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
775	
776	interface ReportReason {
777	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
778	  readonly pointer?: string;
779	  readonly message: string;
780	}
781	
782	interface ReportExample {
783	  readonly method: HttpMethod;
784	  readonly path: string;
785	  readonly headers: { readonly [name: string]: string };
786	  readonly body: string;
787	}
788	
789	interface EndpointReport {
790	  readonly method: HttpMethod;
791	  readonly path: string;
792	  readonly compatible: boolean;
793	  readonly reasons: readonly ReportReason[];
794	  readonly example?: ReportExample;
795	}
796	
797	interface CompareReport {
798	  readonly compatible: boolean;
799	  readonly oldFile: string;
800	  readonly newFile: string;
801	  readonly endpoints: readonly EndpointReport[];
802	}
803	
804	interface BodyViolation {
805	  readonly pointer: string;
806	  readonly message: string;
807	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
808	  readonly value: unknown;
809	}
810	
811	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组。
812	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
813	function sampleValue(rule: BodyRule): unknown {
814	  switch (rule.kind) {
815	    case 'string':
816	      return 'contractlab';
817	    case 'number':
818	    case 'integer':
819	      return 0;
820	    case 'boolean':
821	      return false;
822	    case 'null':
823	      return null;
824	    case 'array':
825	      return [];
826	    case 'object': {
827	      const obj: Record<string, unknown> = Object.create(null);
828	      for (const [name, field] of rule.fields) {
829	        if (field.required) {
830	          obj[name] = sampleValue(field.rule);
831	        }
832	      }
833	      return obj;
834	    }
835	  }
836	}
837	
838	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
839	function sampleObjectWith(
840	  rule: Extract<BodyRule, { kind: 'object' }>,
841	  name: string,
842	  value: unknown,
843	): Record<string, unknown> {
844	  const obj = sampleValue(rule) as Record<string, unknown>;
845	  obj[name] = value;
846	  return obj;
847	}
848	
849	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
850	function violateValue(rule: BodyRule): unknown {
851	  switch (rule.kind) {
852	    case 'number':
853	      return 'contractlab'; // 非数字
854	    case 'integer':
855	      return 0.5; // 非整数
856	    default:
857	      return 0; // 非 string / boolean / null / object / array
858	  }
859	}
860	
861	function kindLabel(rule: BodyRule): string {
862	  if (rule.kind === 'object') {
863	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
864	  }
865	  return rule.kind;
866	}
867	
868	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
869	function freshFieldName(
870	  oldFields: ReadonlyMap<string, FieldRule>,
871	  newFields: ReadonlyMap<string, FieldRule>,
872	): string {
873	  for (let i = 0; ; i += 1) {
874	    const name = i === 0 ? 'extra' : `extra_${i}`;
875	    if (!oldFields.has(name) && !newFields.has(name)) {
876	      return name;
877	    }
878	  }
879	}
880	
881	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
882	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
883	// 可空（nullable:true 或 type:null）规则的接受集合含 null：先单独比较 null 的
884	// 接受性，再比较双方的非 null 部分——可空不能掩盖非 null 约束的变化。
885	function collectViolations(
886	  oldRule: BodyRule,
887	  newRule: BodyRule,
888	  pointer: string,
889	  out: BodyViolation[],
890	): void {
891	  const oldAcceptsNull = oldRule.nullable || oldRule.kind === 'null';
892	  const newAcceptsNull = newRule.nullable || newRule.kind === 'null';
893	  if (oldAcceptsNull && !newAcceptsNull) {
894	    // null 本身就是完整反例；嵌套位置由外层调用方包上必要的父对象与必填字段
895	    out.push({ pointer, value: null, message: '旧规则接受 null，新规则不接受 null' });
896	  }
897	  // type:null 的旧规则只接受 null（上面已比较），没有非 null 值需要再比
898	  if (oldRule.kind === 'null') {
899	    return;
900	  }
901	  // 新规则只接受 null：旧规则的任意非 null 样本都是反例
902	  if (newRule.kind === 'null') {
903	    out.push({
904	      pointer,
905	      value: sampleValue(oldRule),
906	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 null`,
907	    });
908	    return;
909	  }
910	
911	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
912	    // 标量（双方都不是 null 类型）：仅同名兼容，外加 integer 放宽为 number；其余组合两集合相交为空或有差异
913	    const compatible =
914	      oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
915	    if (!compatible) {
916	      // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
917	      const value =
918	        oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
919	      out.push({
920	        pointer,
921	        value,
922	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
923	      });
924	    }
925	    return;
926	  }
927	
928	  if (newRule.kind === 'array') {
929	    if (oldRule.kind !== 'array') {
930	      out.push({
931	        pointer,
932	        value: sampleValue(oldRule),
933	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
934	      });
935	      return;
936	    }
937	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
938	    const sub: BodyViolation[] = [];
939	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
940	    for (const s of sub) {
941	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
942	    }
943	    return;
944	  }
945	
946	  // newRule.kind === 'object'
947	  if (oldRule.kind !== 'object') {
948	    out.push({
949	      pointer,
950	      value: sampleValue(oldRule),
951	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
952	    });
953	    return;
954	  }
955	
956	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
957	  for (const [name, newField] of newRule.fields) {
958	    if (!newField.required) {
959	      continue;
960	    }
961	    const oldField = oldRule.fields.get(name);
962	    if (!oldField || !oldField.required) {
963	      out.push({
964	        pointer: `${pointer}/${escapePointerSegment(name)}`,
965	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
966	        value: sampleValue(oldRule),
967	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
968	      });
969	    }
970	  }
971	
972	  // (b) 旧规则声明的字段，在新规则下仍须被接受
973	  for (const [name, oldField] of oldRule.fields) {
974	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
975	    const newField = newRule.fields.get(name);
976	    if (!newField) {
977	      if (!newRule.additionalProperties) {
978	        out.push({
979	          pointer: childPointer,
980	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
