982	        });
983	      }
984	      continue;
985	    }
986	    const sub: BodyViolation[] = [];
987	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
988	    for (const s of sub) {
989	      out.push({
990	        pointer: s.pointer,
991	        message: s.message,
992	        value: sampleObjectWith(oldRule, name, s.value),
993	      });
994	    }
995	  }
