1093	function compareConfigs(
1094	  oldSpecs: readonly EndpointSpec[],
1095	  newSpecs: readonly EndpointSpec[],
1096	  oldFile: string,
1097	  newFile: string,
1098	): CompareReport {
1099	  const newByKey = new Map<string, EndpointSpec>();
1100	  for (const spec of newSpecs) {
1101	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1102	  }
1103	  const endpoints = oldSpecs.map((spec) =>
1104	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1105	  );
1106	  return {
1107	    compatible: endpoints.every((ep) => ep.compatible),
1108	    oldFile,
1109	    newFile,
1110	    endpoints,
1111	  };
1112	}
