1114	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1115	  const oldFile = path.resolve(oldArg);
1116	  const newFile = path.resolve(newArg);
1117	
1118	  const attempt = async (
1119	    file: string,
1120	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1121	    try {
1122	      return { specs: await loadSpecsFromFile(file) };
1123	    } catch (e) {
1124	      return { error: describeError(e) };
1125	    }
1126	  };
1127	
1128	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1129	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1130	  let failed = false;
1131	  if (oldResult.error !== undefined) {
1132	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1133	    failed = true;
1134	  }
1135	  if (newResult.error !== undefined) {
1136	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1137	    failed = true;
1138	  }
1139	  if (failed) {
1140	    process.exit(2);
1141	  }
1142	
1143	  const report = compareConfigs(
1144	    oldResult.specs as EndpointSpec[],
1145	    newResult.specs as EndpointSpec[],
1146	    oldFile,
1147	    newFile,
1148	  );
1149	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1150	  process.exit(report.compatible ? 0 : 1);
1151	}
