1269	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1270	function unescapeRefSegment(
1271	  segment: string,
1272	  ref: string,
1273	  ctx: ImportCtx,
1274	  where: string,
1275	): string {
1276	  let out = '';
1277	  for (let i = 0; i < segment.length; i += 1) {
1278	    const ch = segment[i];
1279	    if (ch === '~') {
1280	      const next = segment[i + 1];
1281	      if (next === '0') {
1282	        out += '~';
1283	        i += 1;
1284	      } else if (next === '1') {
1285	        out += '/';
1286	        i += 1;
1287	      } else {
1288	        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
1289	      }
1290	    } else {
1291	      out += ch;
1292	    }
1293	  }
1294	  return out;
1295	}
