1297	// 解析一层 $ref：node 是“只含 $ref 的引用节点”时返回目标与新的位置/引用链，
1298	// 否则返回 null。外部引用、非法指针、目标缺失、循环引用都在此拒绝。
1299	function dereference(
1300	  node: Record<string, unknown>,
1301	  ctx: ImportCtx,
1302	  where: string,
1303	  refChain: readonly string[],
1304	): { target: unknown; where: string; refChain: readonly string[] } | null {
1305	  if (!hasOwnKey(node, '$ref')) {
1306	    return null;
1307	  }
1308	  if (Object.keys(node).length !== 1) {
1309	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1310	  }
1311	  const ref = node.$ref;
1312	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1313	    importFail(
1314	      ctx,
1315	      where,
1316	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1317	    );
1318	  }
1319	  if (refChain.includes(ref as string)) {
1320	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
1321	  }
1322	  const fragment = (ref as string).slice(1);
1323	  let target: unknown = ctx.doc;
1324	  if (fragment !== '') {
1325	    if (!fragment.startsWith('/')) {
1326	      importFail(ctx, where, `$ref "${ref as string}" 不是合法的 JSON Pointer 片段`);
1327	    }
1328	    const segments = fragment
1329	      .slice(1)
1330	      .split('/')
1331	      .map((seg) => unescapeRefSegment(seg, ref as string, ctx, where));
1332	    let traversed = '#';
1333	    for (const segment of segments) {
1334	      traversed = `${traversed}/${escapePointerSegment(segment)}`;
1335	      if (Array.isArray(target)) {
1336	        if (!/^(0|[1-9]\d*)$/.test(segment) || Number(segment) >= target.length) {
1337	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 超出数组范围`);
1338	        }
1339	        target = target[Number(segment)];
1340	      } else if (isPlainObject(target)) {
1341	        if (!hasOwnKey(target, segment)) {
1342	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 缺失`);
1343	        }
1344	        target = target[segment];
1345	      } else {
1346	        importFail(ctx, where, `$ref "${ref as string}" 无法继续解析：${traversed} 不是对象或数组`);
1347	      }
1348	    }
1349	  }
1350	  return { target, where: `${where} -> ${ref as string}`, refChain: [...refChain, ref as string] };
1351	}
