1356	function resolveSchemaNode(
1357	  rawNode: unknown,
1358	  ctx: ImportCtx,
1359	  where: string,
1360	  refChain: readonly string[],
1361	): { n: Record<string, unknown>; nodeWhere: string; chain: readonly string[] } {
1362	  let node = rawNode;
1363	  let nodeWhere = where;
1364	  let chain = refChain;
