1368	      importFail(ctx, nodeWhere, 'schema 必须是对象');
1369	    }
1370	    const ref = dereference(node, ctx, nodeWhere, chain);
1371	    if (!ref) {
1372	      break;
1373	    }
1374	    node = ref.target;
1375	    nodeWhere = ref.where;
1376	    chain = ref.refChain;
1377	  }
