1439	// schema（或引用链尽头的 schema）-> 规范化规则
1440	function schemaToNorm(
1441	  rawNode: unknown,
1442	  ctx: ImportCtx,
1443	  where: string,
1444	  refChain: readonly string[],
1445	): NormRule {
1446	  const { n, nodeWhere, chain } = resolveSchemaNode(rawNode, ctx, where, refChain);
