1568	// 按“全部分支都接受 null”统一判定。
1569	function scalarIntersection(
1570	  a: NormRule,
1571	  b: NormRule,
1572	): { kind: 'string' | 'number' | 'integer' | 'boolean'; nullable: boolean } | null {
1573	  if (a.kind === b.kind) {
1574	    return { kind: a.kind, nullable: false } as {
1575	      kind: 'string' | 'number' | 'integer' | 'boolean';
1576	      nullable: boolean;
1577	    };
1578	  }
1579	  if (
1580	    (a.kind === 'number' && b.kind === 'integer') ||
1581	    (a.kind === 'integer' && b.kind === 'number')
1582	  ) {
1583	    return { kind: 'integer', nullable: false };
1584	  }
1585	  return null;
