1641	        forbiddener = flat[i];
1642	      }
1643	    }
1644	
1645	    if (forbiddener !== undefined) {
1646	      if (isRequired) {
1647	        return {
1648	          tag: 'empty',
1649	          reason:
1650	            `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现` +
1651	            '（未声明且 additionalProperties 为 false），交集为空',
1652	          loc: forbiddener.loc,
1653	        };
1654	      }
1655	      // 可选且被禁止：结果中不声明该字段即“禁止出现”。其余声明分支的取值交集
1656	      // 为何都无关紧要——该字段根本不能出现（声明分支中的非法 schema 仍在
