1875	function importOperationBodyRule(
1876	  operation: Record<string, unknown>,
1877	  method: HttpMethod,
1878	  ctx: ImportCtx,
1879	  opWhere: string,
1880	): unknown {
1881	  if (!hasOwnKey(operation, 'requestBody')) {
1882	    return undefined;
1883	  }
1884	  const rbWhere = `${opWhere}.requestBody`;
1885	  if (method === 'GET') {
