1887	  }
1888	  // requestBody 本身也可以是本文件内 $ref（可层层引用）
1889	  let node: unknown = operation.requestBody;
1890	  let nodeWhere = rbWhere;
1891	  let chain: readonly string[] = [];
1892	  for (;;) {
1893	    if (!isPlainObject(node)) {
