2083	// utf-8 文本必须能无损编码往返：孤立代理项（lone surrogate）按 UTF-8 编码时
2084	// 会被替换为 U+FFFD，即使替换后的字节数恰好与 bodyBytes 吻合也不再是原始字节，
2085	// 必须拒绝（verify 与 replay 共用此校验）。
2086	function hasLoneSurrogate(text: string): boolean {
2087	  for (let i = 0; i < text.length; i += 1) {
2088	    const code = text.charCodeAt(i);
