2327	async function runVerify(requestsArg: string, configArg: string): Promise<never> {
2328	  const requestsFile = path.resolve(requestsArg);
2329	  const configFile = path.resolve(configArg);
2330	
2331	  const attemptSnapshot = async (): Promise<{ requests?: SnapshotRequest[]; error?: string }> => {
2332	    try {
2333	      return { requests: await loadSnapshotFromFile(requestsFile) };
2334	    } catch (e) {
2335	      return { error: describeError(e) };
2336	    }
2337	  };
2338	  const attemptSpecs = async (): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
2339	    try {
2340	      return { specs: await loadSpecsFromFile(configFile) };
2341	    } catch (e) {
2342	      return { error: describeError(e) };
2343	    }
2344	  };
2345	
2346	  // 两份输入都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
2347	  const [snapResult, specResult] = await Promise.all([attemptSnapshot(), attemptSpecs()]);
2348	  let failed = false;
2349	  if (snapResult.error !== undefined) {
2350	    process.stderr.write(`${APP_NAME}: verify 请求快照：${snapResult.error}\n`);
2351	    failed = true;
2352	  }
2353	  if (specResult.error !== undefined) {
2354	    process.stderr.write(`${APP_NAME}: verify 场景配置：${specResult.error}\n`);
2355	    failed = true;
2356	  }
2357	  if (failed) {
2358	    process.exit(2);
2359	  }
2360	
2361	  const report = verifyRequests(
2362	    snapResult.requests as SnapshotRequest[],
2363	    specResult.specs as EndpointSpec[],
2364	    requestsFile,
2365	    configFile,
2366	  );
2367	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
2368	  process.exit(report.rejected === 0 ? 0 : 1);
2369	}
