2409	// 一条待重放的请求：共享快照校验之上再经重放专用校验
2410	interface ReplayRequest {
2411	  readonly id: number;
2412	  readonly method: 'GET' | 'POST';
2413	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
2414	  readonly target: string;
