2424	function validateReplayTarget(target: string, where: string): void {
2425	  if (target.length === 0 || !target.startsWith('/')) {
2426	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
2427	  }
2428	  for (const ch of target) {
2429	    const code = ch.charCodeAt(0);
2430	    if (code <= 0x20 || code === 0x7f) {
2431	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
2432	    }
2433	    if (code > 0xff) {
2434	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
2435	    }
2436	  }
2437	}
