2439	// 过滤并校验待发送的业务头：剥离 Host/Expect/逐跳/分帧头（含 Connection
2440	// 指名的头），其余按原顺序、大小写与重复项保留；保留的头名称与值必须可发送。
2441	function filterReplayHeaders(
2442	  rawHeaders: readonly string[],
2443	  where: string,
2444	): [string, string][] {
2445	  const connectionNamed = new Set<string>();
2446	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2447	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
2448	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
2449	        const name = token.trim().toLowerCase();
2450	        if (name !== '') {
2451	          connectionNamed.add(name);
2452	        }
2453	      }
2454	    }
2455	  }
2456	  const out: [string, string][] = [];
2457	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2458	    const name = rawHeaders[j] as string;
2459	    const value = rawHeaders[j + 1] as string;
2460	    const lower = name.toLowerCase();
2461	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
2462	      continue;
2463	    }
2464	    if (!HEADER_NAME_RE.test(name)) {
2465	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
2466	    }
2467	    for (let k = 0; k < value.length; k += 1) {
2468	      const code = value.charCodeAt(k);
2469	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
