2563	interface ReplayResponse {
2564	  readonly status: number;
2565	  readonly body: Buffer;
2566	}
2567	
2568	type ReplayExchange =
2569	  | { readonly ok: true; readonly response: ReplayResponse }
2570	  | { readonly ok: false; readonly reason: string };
2571	
2572	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
2573	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
2574	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
2575	  return new Promise((resolve) => {
2576	    let settled = false;
2577	    const done = (outcome: ReplayExchange): void => {
2578	      if (!settled) {
2579	        settled = true;
2580	        clearTimeout(timer);
2581	        resolve(outcome);
2582	      }
2583	    };
2584	
2585	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
2586	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
2587	    const headers: string[] = [];
2588	    for (const [name, value] of request.headers) {
2589	      headers.push(name, value);
2590	    }
2591	    headers.push('Host', `127.0.0.1:${port}`);
2592	    headers.push('Content-Length', String(request.body.byteLength));
2593	    headers.push('Connection', 'close');
2594	
2595	    const req = http.request({
2596	      host: '127.0.0.1',
2597	      port,
2598	      method: request.method,
2599	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
2600	      headers,
2601	      agent: false, // 不连接池化：一次一条，每条只尝试一次
2602	    });
2603	
2604	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
2605	    const timer = setTimeout(() => {
2606	      req.destroy();
2607	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
2608	    }, timeoutMs);
2609	
2610	    req.on('response', (res) => {
2611	      const chunks: Buffer[] = [];
2612	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
2613	      res.on('end', () => {
2614	        done({
2615	          ok: true,
2616	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
2617	        });
2618	      });
2619	      res.on('aborted', () => {
2620	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
2621	      });
2622	      res.on('error', (e: unknown) => {
2623	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
2624	      });
2625	      res.on('close', () => {
2626	        if (!res.complete) {
2627	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
2628	        }
2629	      });
2630	    });
2631	    req.on('error', (e: Error) => {
2632	      done({ ok: false, reason: `通信失败：${e.message}` });
2633	    });
2634	    req.end(request.body);
2635	  });
2636	}
