2759	      return { ok: false, version: activeState.version, error: describeError(e) };
2760	    }
2761	  });
2762	  // 失败也不能打断后续 reload 的排队
2763	  reloadChain = job.then(
2764	    () => undefined,
2765	    () => undefined,
2766	  );
2767	  return job;
2768	}
