2822	//
2823	// 业务/框架响应在“请求完整接收”那一刻就构造为一份计划快照：
2824	// 记录中保存的状态/应用层头/正文与随后真正写上线的字节共用同一份数据，
2825	// reload 不影响在途请求（它持有的是快照而非当前配置）。
2826	
2827	function freezeHeaders(headers: { [name: string]: string }): { readonly [name: string]: string } {
2828	  return Object.freeze(headers);
2829	}
