2880	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
2881	function writePlanned(
2882	  res: http.ServerResponse,
2883	  planned: PlannedResponseSnapshot,
2884	  recordId: number,
2885	): void {
2886	  try {
2887	    res.writeHead(planned.status, { ...planned.headers });
