2910	// 延迟结束才按接收时的计划快照发送；即便客户端提前断开也继续计时（消费在预留时已成立）
2911	function schedulePlannedResponse(
2912	  res: http.ServerResponse,
2913	  planned: PlannedResponseSnapshot,
2914	  delay: number,
2915	  recordId: number,
2916	): void {
2917	  const timer = setTimeout(() => {
2918	    pendingTimers.delete(timer);
2919	    writePlanned(res, planned, recordId);
2920	  }, delay);
2921	  pendingTimers.add(timer);
2922	}
