2969	async function dispatch(
2970	  req: http.IncomingMessage,
2971	  res: http.ServerResponse,
2972	): Promise<void> {
2973	  res.on('error', () => {
2974	    // 写已销毁套接字等错误无需让进程崩溃
2975	  });
2976	
2977	  const method = String(req.method);
2978	  const target = String(req.url ?? '/'); // 含查询串的原始请求目标
2979	  const pathname = target.split('?')[0]; // 查询串不参与匹配
2980	
2981	  const { outcome, body } = await receiveBody(req, res);
2982	  if (outcome !== 'received') {
2983	    // aborted：未完整接收，不匹配、不预留、不推进任何序列，也不创建记录
2984	    // too-large：已回复 413，不创建记录、不消费序列
2985	    return;
2986	  }
2987	
2988	  // 管理范围：/__contractlab 本身及 /__contractlab/ 前缀。
2989	  // 其中所有请求都不记录、不消费业务序列（含未知子路径的 404）。
2990	  if (pathname === ADMIN_BASE || pathname.startsWith(ADMIN_PREFIX)) {
2991	    await handleAdmin(method, pathname, res);
2992	    return;
2993	  }
2994	
2995	  // 完整接收且不在管理范围：此刻创建记录并取得进程内递增编号。
2996	  // 编号只取决于完整接收顺序，与接口序列的消费位置互不相关。
2997	  const state = activeState;
2998	  const record = requestLog.create({
2999	    method,
3000	    target,
3001	    path: pathname,
3002	    rawHeaders: req.rawHeaders,
3003	    body,
3004	    configVersion: state.version,
3005	  });
3006	  attachDeliveryTracking(res, record.id);
3007	
3008	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
3009	  const endpoint =
3010	    method === 'GET' || method === 'POST'
3011	      ? state.endpoints.get(`${method} ${pathname}`)
3012	      : undefined;
3013	
3014	  if (!endpoint) {
3015	    // 未匹配请求：404，不消费、无消费位置
3016	    record.matched = false;
3017	    record.endpoint = `${method} ${pathname}`;
3018	    const planned = buildFrameworkPlanned(
3019	      404,
3020	      state.version,
3021	      'not found\n',
3022	      'text/plain; charset=utf-8',
3023	    );
3024	    record.plannedResponse = planned;
3025	    writePlanned(res, planned, record.id);
3026	    return;
3027	  }
3028	  record.matched = true;
3029	  record.endpoint = endpoint.key;
3030	
3031	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
3032	  // 规则、序列与版本均取自上面同一快照 state。
3033	  if (endpoint.bodyRule) {
3034	    const report = validateBodyWithContentType(
3035	      req.headers['content-type'],
3036	      body,
3037	      endpoint.bodyRule,
3038	    );
3039	    if (report) {
3040	      record.bodyValidationPassed = false;
3041	      record.bodyRejection = report;
3042	      const planned = buildFrameworkPlanned(
3043	        400,
3044	        state.version,
3045	        `${JSON.stringify(report)}\n`,
3046	        'application/json; charset=utf-8',
3047	      );
3048	      record.plannedResponse = planned;
3049	      writePlanned(res, planned, record.id);
3050	      return;
3051	    }
3052	    record.bodyValidationPassed = true;
3053	  }
3054	
