3156	async function startServer(configArg: string, port: number): Promise<void> {
3157	  configFile = path.resolve(configArg);
3158	
3159	  // 先读配置：配置无效时根本不会创建监听
3160	  activeState = await loadStateFromFile(configFile, 1);
3161	
3162	  server = http.createServer((req, res) => {
3163	    dispatch(req, res).catch(() => {
3164	      try {
3165	        req.socket.destroy();
3166	      } catch {
3167	        // 套接字可能已销毁
3168	      }
3169	    });
3170	  });
3171	
3172	  await new Promise<void>((resolve, reject) => {
3173	    server.once('error', reject);
3174	    // 仅监听本机回环地址
3175	    server.listen(port, '127.0.0.1', resolve);
3176	  });
3177	
3178	  const address = server.address();
3179	  const actualPort = typeof address === 'object' && address ? address.port : port;
3180	  process.stdout.write(
3181	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
3182	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
3183	  );
3184	
3185	  const onSignal = (): void => shutdown();
3186	  process.on('SIGINT', onSignal);
3187	  process.on('SIGTERM', onSignal);
3188	}
