3277	
3278	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
3279	    if (inline !== undefined) {
3280	      return [inline, index];
3281	    }
3282	    const value = argv[index + 1];
3283	    if (value === undefined) {
3284	      cliFail(`serve: 参数 ${flag} 缺少取值`);
3285	    }
3286	    return [value as string, index + 1];
3287	  };
3288	
3289	  for (let i = 0; i < argv.length; i += 1) {
3290	    const token = argv[i];
3291	    if (token === '--help' || token === '-h') {
3292	      process.stdout.write(`${helpText()}\n`);
3293	      process.exit(0);
3294	    }
3295	
3296	    let flag = token;
3297	    let inline: string | undefined;
3298	    const eq = token.indexOf('=');
3299	    if (eq >= 0) {
3300	      flag = token.slice(0, eq);
3301	      inline = token.slice(eq + 1);
3302	    }
3303	
3304	    if (flag === '--config' || flag === '-c') {
3305	      [config, i] = readValue(flag, inline, i);
