    },
    newRule: {
      type: 'object',
      fields: { a: { type: 'integer', required: true } },
      additionalProperties: false,
    },
  },
  {
    name: 'optional->required',
    oldRule: {
      type: 'object',
      fields: { a: { type: 'integer' } },
      additionalProperties: false,
    },
    newRule: {
