        },
      },
      additionalProperties: false,
    },
    newRule: {
      type: 'object',
      fields: {
        buyer: {
          type: 'object',
          required: true,
          fields: { name: { type: 'integer', required: true } },
          additionalProperties: false,
        },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'nested:new-required-field',
    oldRule: {
      type: 'object',
      fields: {
        buyer: {
          type: 'object',
          required: true,
          fields: { name: { type: 'string', required: true } },
          additionalProperties: false,
        },
      },
